import React, { useState } from 'react';

const SECTORS = [
  'Maturity Domain',
  'SMEs',
  'Large Ent.',
  'Finance',
  'Healthcare',
  'Public Inst.',
  'Critical Infra.',
  'SME',
  'Large Enterprise',
  'Public Institutions',
  'Critical Infrastructure',
  'SaaS/Cloud',
  'Public',
];

interface LoginProps {
  onLogin: (username: string, sector: string) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [username, setUsername] = useState('');
  const [sector, setSector] = useState(SECTORS[0]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (username.trim()) {
      onLogin(username.trim(), sector);
    }
  };

  return (
    <div className="flex items-center justify-center min-h-screen bg-[#0f0f23]">
      <form onSubmit={handleSubmit} className="bg-[#1e1e3f] p-8 rounded-lg shadow-lg w-full max-w-md flex flex-col gap-6">
        <h2 className="text-2xl font-bold text-blue-400 mb-2 text-center">Welcome</h2>
        <div>
          <label className="block text-gray-300 mb-2" htmlFor="username">Username</label>
          <input
            id="username"
            type="text"
            className="w-full p-3 rounded bg-[#0f0f23] border border-gray-700 text-gray-100 focus:outline-none focus:border-blue-500"
            value={username}
            onChange={e => setUsername(e.target.value)}
            required
            autoFocus
          />
        </div>
        <div>
          <label className="block text-gray-300 mb-2" htmlFor="sector">Sector</label>
          <select
            id="sector"
            className="w-full p-3 rounded bg-[#0f0f23] border border-gray-700 text-gray-100 focus:outline-none focus:border-blue-500"
            value={sector}
            onChange={e => setSector(e.target.value)}
          >
            {SECTORS.map(s => (
              <option key={s} value={s}>{s}</option>
            ))}
          </select>
        </div>
        <button
          type="submit"
          className="bg-blue-600 text-white font-medium rounded-lg px-5 py-3 transition hover:bg-blue-700 disabled:bg-gray-500 disabled:cursor-not-allowed"
          disabled={!username.trim()}
        >
          Enter
        </button>
      </form>
    </div>
  );
};

export default Login;
